<?php require __DIR__.'/inc/header.php';$title='Orders';$pdo=db();if(is_post()){verify_csrf();$id=(int)post('id');$status=(string)post('status');$pay=(string)post('payment_status');$pdo->prepare('UPDATE orders SET order_status=?,payment_status=?,courier=?,tracking_number=? WHERE id=?')->execute([$status,$pay,post('courier'),post('tracking'),$id]);flash('success','Order updated.');redirect('/admin/orders.php?id='.$id);}if(isset($_GET['id'])){$id=(int)$_GET['id'];$s=$pdo->prepare('SELECT * FROM orders WHERE id=?');$s->execute([$id]);$order=$s->fetch();$it=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?');$it->execute([$id]);$items=$it->fetchAll();}else{$order=null;$items=[];$orders=$pdo->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();}if(isset($order)){}?><?php if(!$order):?><div class="flex justify-between mb-6"><div><div class="text-xs tracking-[.2em] text-slate-400 font-black">SALES</div><h1 class="text-3xl font-black">Orders</h1></div></div><div class="bg-white border rounded-2xl overflow-hidden"><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Order</th><th class="p-3 text-left">Customer</th><th class="p-3 text-left">Total</th><th class="p-3 text-left">Payment</th><th class="p-3 text-left">Status</th></tr></thead><tbody><?php foreach($orders as $o):?><tr class="border-t"><td class="p-3 font-bold"><a href="?id=<?=$o['id']?>"><?=e($o['order_number'])?></a></td><td class="p-3"><?=e($o['customer_name'])?><div class="text-xs text-slate-400"><?=e($o['customer_phone'])?></div></td><td class="p-3 font-bold"><?=money($o['total'])?></td><td class="p-3"><?=strtoupper(e($o['payment_method']))?></td><td class="p-3"><?=ucwords(str_replace('_',' ',e($o['order_status'])))?></td></tr><?php endforeach;?></tbody></table></div></div><?php else:?><div class="flex items-center gap-3 mb-6"><a href="/admin/orders.php" class="text-slate-500">← Orders</a><h1 class="text-3xl font-black"><?=e($order['order_number'])?></h1></div><div class="grid lg:grid-cols-[1fr_360px] gap-6"><div class="bg-white border rounded-2xl p-5"><div class="font-black">Items</div><?php foreach($items as $i):?><div class="flex justify-between py-4 border-b"><div><b><?=e($i['product_name'])?></b><div class="text-xs text-slate-400">Qty <?=$i['quantity']?> · <?=e($i['size'])?> <?=e($i['color'])?><?php if($i['custom_name']):?> · <?=e($i['custom_name'])?> #<?=e($i['custom_number'])?><?php endif;?></div></div><b><?=money($i['total'])?></b></div><?php endforeach;?><div class="text-right font-black text-xl mt-4">Total <?=money($order['total'])?></div><div class="mt-6 text-sm bg-slate-50 rounded-xl p-4"><b>Shipping:</b> <?=e($order['customer_address'])?>, <?=e($order['area'])?>, <?=e($order['city'])?><br><b>Phone:</b> <?=e($order['customer_phone'])?></div></div><form method="post" class="bg-white border rounded-2xl p-5 h-fit"><?=csrf_input()?><input type="hidden" name="id" value="<?=$order['id']?>"><div class="font-black">Update Order</div><label class="block text-xs font-bold mt-4">Order Status<select name="status" class="w-full mt-1 rounded-xl border-slate-200"><?php foreach(['pending','confirmed','processing','ready_to_ship','shipped','delivered','cancelled','returned','refunded','failed'] as $s):?><option value="<?=$s?>" <?=($order['order_status']===$s?'selected':'')?>><?=ucwords(str_replace('_',' ',$s))?></option><?php endforeach;?></select></label><label class="block text-xs font-bold mt-3">Payment<select name="payment_status" class="w-full mt-1 rounded-xl border-slate-200"><option <?=($order['payment_status']==='pending'?'selected':'')?>>pending</option><option <?=($order['payment_status']==='paid'?'selected':'')?>>paid</option><option <?=($order['payment_status']==='failed'?'selected':'')?>>failed</option></select></label><input name="courier" value="<?=e($order['courier'])?>" placeholder="Courier" class="w-full mt-3 rounded-xl border-slate-200"><input name="tracking" value="<?=e($order['tracking_number'])?>" placeholder="Tracking / consignment ID" class="w-full mt-3 rounded-xl border-slate-200"><button class="w-full mt-4 py-3 rounded-xl bg-slate-950 text-white font-black">Save Status</button></form></div><?php endif;?><?php require __DIR__.'/inc/footer.php';?>
